entries[216624] = { ["name"] = "Mark of Arrogance", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: Attackers suffer a Mark of Arrogance inflicting Shadow damage every 2 sec for 10 sec and stacking up to 5 times.\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
entries[216625] = { ["name"] = "Quick Strike", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: Your melee abilities have a 100% chance to trigger 4 to 7 additional autoattacks. (10 Sec Cooldown)\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
entries[216626] = { ["name"] = "Slay", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: When you attack an enemy beneath 10% health you will attempt to Slay them, inflicting Shadow damage equal to 100% of your maximum health.\n\nYou will only attempt to Slay an enemy once.\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
entries[216627] = { ["name"] = "Tinkmaster's Shield", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: Grants a shield absorbing damage equal to 15% of your total health.\n\nThis shield will regenerate after not suffering any damage for 5 sec.\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
entries[216628] = { ["name"] = "Victory Fire", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: Slaying an enemy causes you to erupt, inflicting Fire damage to enemies and restoring health to allies within 12 yards.\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
entries[216629] = { ["name"] = "Blink", ["text"] = "Cogwheel Gem\nBinds when picked up\nUnique\nEquip: Learn the following spell.\n\nBlink\nTeleports you forward 20 yds or until reaching an obstacle, and frees you from all stuns and bonds.\nRequires level 10 to 80 ( 80)\n\"Fits in a Cogwheel socket.\"" }
entries[216630] = { ["name"] = "Heroic Leap", ["text"] = "Cogwheel Gem\nBinds when picked up\nUnique\nEquip: Learn the following spell.\n\nHeroic Leap\nLeap through the air toward a target location, slamming down with destructive force to deal (23.5% of Spell Power + 23.5% of Attack Power) Physical damage to all enemies within 8 yards.\nRequires level 10 to 80 ( 80)\n\"Fits in a Cogwheel socket.\"" }
