entries[216647] = { ["name"] = "Hailstorm", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: Every 3 sec build a charge of Hailstorm. Upon reaching 10 stacks, unleash hail on enemies within 50 yards. Each impact inflicts Frost damage and applies Numbing Cold.\n\nNumbing Cold\nReduces movement speed by 30% and reduces damage dealt by 10%. Attacking removes a stack of Numbing Cold.\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
entries[216648] = { ["name"] = "Cold Front", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: Your abilities have a chance to grant up to 5 allies a shield absorbing damage, split evenly, and inflict Numbing Cold to all enemies within 50 yards.\n\nNumbing Cold\nReduces movement speed by 30% and reduces damage dealt by 10%. Attacking removes a stack of Numbing Cold.\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
entries[216649] = { ["name"] = "Brittle", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: Your abilities apply Brittle to enemies, accruing 10% of damage you deal. When a Brittle enemy is slain, it explodes, inflicting Frost damage to enemies within 12 yards, divided evenly.\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
