entries[216711] = { ["name"] = "Chi-ji, the Red Crane", ["text"] = "Meta Gem\nBinds when picked up\nUnique\nEquip: Learn the following spell.\n\nChi-Ji, the Red Crane\nIncreases movement speed by 50%, grants immunity to movement impairing effects, and grants the following spells for 20 sec.\n\nCrane Rush\nRush forward a short distance.\n\nBlazing Nova\nA fiery blast hurls you backwards, inflicting Fire damage to enemies and restoring health to allies within 10 yards.\n\nHope's Plumage\nEvery 2 sec, Chi-Ji sheds a feather. Touching the feather launches a volley of Hope's Flame to injure enemies and heal allies.\n\nHope's Flame\nEvery 2 sec, inflicts Fire damage or restores health to 5 enemies or allies within 30 yards.\nRequires level 10 to 80 ( 80)\n\"Fits in a Meta socket.\"" }
entries[216712] = { ["name"] = "Bronze Timepiece", ["text"] = "Quest Item\nUnique\nRequires level 10 to 80 ( 80)\n\"Using this will rewind time and reset your position.\"" }
entries[216719] = { ["name"] = "Keg Leg's Cannonade", ["text"] = "Consumable\nUse: Signal Keg Leg to target your position with a barrage of cannon fire. The barrage inflicts heavy damage to ALL targets caught in the barrage.\nSell Price:" }
entries[216720] = { ["name"] = "Valuable Parts", ["text"] = "Quest Item\n\"A greasy assemblage of esoteric machine parts.\"" }
