entries[216882] = { ["name"] = "Log Entry 467-21-5", ["text"] = "Quest Item\n\"Observation: Mycelium expansion noted at an alarming rate, infiltrating neighboring vegetation. Fungarians display a heightened response to environmental stimuli, showcasing a potential shift in their ecological behavior.\"\n<Right Click to Read>" }
entries[216888] = { ["name"] = "Log Entry 652-12-3", ["text"] = "Quest Item\n\"Notation: Fungarians demonstrate aggressive mycorrhizal interactions, outcompeting nearby fungal species. The accelerated growth raises concerns about potential ecological imbalances in the affected area.\"\n<Right Click to Read>" }
entries[216889] = { ["name"] = "Log Entry 893-03-9", ["text"] = "Quest Item\n\"Observation: Fungarians now spreading beyond the initial study site. Aggressive mycelial intrusion observed in unexpected habitats. Urgent investigation needed to assess the broader ecological impact of this newfound behavior (...)\"\n<Right Click to Read>" }
