entries[217162] = { ["name"] = "Necklace of Kobold Teeth", ["text"] = "\"Small, sharp, and probably stolen.\"\nSell Price:" }
entries[217163] = { ["name"] = "Well-Worn Doll", ["text"] = "\"\"Mr. Snugglewick\" is shakily written on the back of the doll.\"\nSell Price:" }
entries[217164] = { ["name"] = "Royal Nailpicker", ["text"] = "\"A captured earthen blade, rusty and dented beyond usefulness. Crusted in things better left unpondered.\"\nSell Price:" }
entries[217165] = { ["name"] = "Zev'kall's Attrition Log", ["text"] = "Quest Item\n\"A detailed description of the losses of nerubian troops at the Siegehold.\"" }
entries[217167] = { ["name"] = "Crusty Chalice", ["text"] = "\"An old boot stained with wine and other, darker, things.\"\nSell Price:" }
entries[217168] = { ["name"] = "Chocolate Coins", ["text"] = "\"Some of the coins have bites taken out. None were unwrapped first.\"\nSell Price:" }
entries[217169] = { ["name"] = "Cloak of Beards", ["text"] = "\"Crudely woven from the shorn, wiry beards of fallen earthen.\"\nSell Price:" }
entries[217170] = { ["name"] = "Backup Candles", ["text"] = "\"Never have enough! - Skitter\"\nSell Price:" }
entries[217171] = { ["name"] = "CANDLE KING DIARY", ["text"] = "\"Thick book. Heavy book. Many words.\"\n<Right Click to Read>\nSell Price:" }
entries[217174] = { ["name"] = "Bronze", ["text"] = "Quest Item\nRequires level 10 to 80 ( 80)\n\"Eternus' infinite allies trade using loose threads of time compressed into bronze coins.\"" }
entries[217175] = { ["name"] = "Sharpscale's Head", ["text"] = "Quest Item\nUnique\n\"Dripping with blood and water, you can smell the fetid stench coming from this even in your bag.\"" }
entries[217176] = { ["name"] = "Hauberk of the Awakened", ["text"] = "Binds when picked up\nChest Mail\n1928 Armor\n+862 [Agility or Intellect]\n+3,652 Stamina\n+ 294 Haste\n+ 734 Mastery\nDurability 165 / 165\nClasses: Evoker\nScales of the Awakened (0/5)\nHauberk of the Awakened\nGauntlets of the Awakened\nCrown of the Awakened\nLegguards of the Awakened\nTalons of the Awakened\n(2) Set Devastation: Disintegrate and Pyre pierce enemies with Obsidian Shards, dealing 18% of damage done as Volcanic damage over 8 sec.\n(2) Set Preservation: Spiritbloom applies a heal over time effect for 40% of healing done over 8 sec. Dream Breath's healing is increased by 15%.\n(2) Set Augmentation: Every third Prescience lasts 100% longer.\n(4) Set Devastation: Empower spells deal 12% increased damage and cause your Obsidian Shards to blaze with power, dealing 200% more damage for 5 sec. During Dragonrage, shards always blaze with power.\n(4) Set Preservation: After casting 4 empower spells, gain Essence Burst immediately and another 3 sec later.\n(4) Set Augmentation: Casting Prescience enhances your next Eruption with smaller fissures for each Prescience you have active, each dealing (110% of Spell Power) damage and extending Ebon Might by 0.2 sec.\nSell Price:" }
