entries[217340] = { ["name"] = "Voyaging Wilderling's Harness", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Voyaging Wilderling.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These playful visitors from another realm thrive while traveling to new lands with new friends.\"\nAchievement:\nAwakening the Dragonflight Raids" }
