entries[217605] = { ["name"] = "Timeless Scroll of Intellect", ["text"] = "Use: Infuses the target with brilliance, increasing their Intellect by 4% for 1 hour.\n\nIf the target is in your party or raid, all party and raid members will be affected.\nRequires level 10 to 80 ( 80)" }
entries[217606] = { ["name"] = "Timeless Scroll of Fortitude", ["text"] = "Use: Infuses the target with vitality, increasing their Stamina by 4% for 1 hour.\n\nIf the target is in your party or raid, all party and raid members will be affected.\nRequires level 10 to 80 ( 80)" }
entries[217607] = { ["name"] = "Timeless Scroll of the Wild", ["text"] = "Use: Infuse a friendly target with the power of the wild, increasing their Versatility by 2% for 1 hour.\n\nIf target is in your party or raid, all party and raid members will be affected.\nRequires level 10 to 80 ( 80)" }
entries[217608] = { ["name"] = "Timeless Scroll of Battle Shout", ["text"] = "Use: Increases the attack power of all raid and party members within 100 yards by 4% for 1 hour.\nRequires level 10 to 80 ( 80)" }
entries[217610] = { ["name"] = "Earthen Memory Gem", ["text"] = "Quest Item\nUnique\n\"This square-cut gem is heavy for its size and emits a faint glow. Engineered for earthen programming and memories, this gem-like cache is removable and can be uploaded to the earthen Archive.\"" }
entries[217612] = { ["name"] = "Zovaal's Shadebeast Collar", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Was I a good boy?\" the soul asked Zovaal. \"No. I'm told you were the worst.\"\nAchievement:\nBack from the Beyond\nCategory:\nExpansion Features" }
entries[217614] = { ["name"] = "Arathi Rations", ["text"] = "Quest Item\n\"A simple stew made from hearty ingredients. Filling, comforting, and lacking salt.\"" }
