entries[217853] = { ["name"] = "<Insert Bespoke Cantrip Gear>", ["text"] = "Binds when picked up\nOff Hand Shield\n9384 Armor\n+520 Strength\n+2,378 Stamina\n+ 310 Critical Strike\n+ 246 Mastery\nSell Price:" }
entries[217891] = { ["name"] = "Cobalt Guardian's Cloak", ["text"] = "Cosmetic\nBinds to Warband\nBack\n1 Armor\nRequires the Cobalt Assembly power to be at High.\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[217892] = { ["name"] = "Emerald Winglord's Shoulders", ["text"] = "Cosmetic\nBinds to Warband\nShoulder Mail\n2 Armor\nDurability 30 / 30\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[217893] = { ["name"] = "Emerald Winglord's Chain", ["text"] = "Cosmetic\nBinds to Warband\nWaist Mail\n2 Armor\nDurability 18 / 18\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[217894] = { ["name"] = "Nerubian Pheromone Secreter", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nFragrance Socket\nFragrance Socket\nEquip: Your spells and abilities have a chance to secrete different pheromones around you. Touching these pheromones will increase your primary stat by 2051 for 20 sec. (20s cooldown)\nSell Price:" }
entries[217895] = { ["name"] = "Volatile Pheromone", ["text"] = "\"A strange chemical swirls within this bottle. It probably doesn't have any long-lasting side effects... right?\"" }
entries[217896] = { ["name"] = "Cinderbrew Mead", ["text"] = "Use: A fairly weak alcoholic beverage.\n\"Filled to the brim with bubbling, steaming mead.\"\nSell Price:" }
entries[217897] = { ["name"] = "Volatile Pheromone", ["text"] = "\"This container shakes from the odd substance within it.\"" }
entries[217898] = { ["name"] = "Prayer of Purged Hatred", ["text"] = "Binds when picked up\nUnique\nThe next attack that reduces you below 35% health triggers Purged Hatred .\n\nPurged Hatred :\nFully restores your health, vigor, and class resources.\nRequires level 10 to 80 ( 80)" }
entries[217899] = { ["name"] = "Prayer of Purged Pride", ["text"] = "Binds when picked up\nUnique\nWhile out of combat, gain Purged Pride .\n\nPurged Pride :\nVanish from sight, entering stealth. Your next attack is guaranteed to be a critical strike.\nRequires level 10 to 80 ( 80)" }
entries[217900] = { ["name"] = "Prayer of Purged Anger", ["text"] = "Binds when picked up\nUnique\nThe next time you are hit, release Purged Anger .\n\nPurged Anger :\nInflicts 2625000 Physical damage to enemies within 8 yards and stuns them for 3 sec.\nRequires level 10 to 80 ( 80)" }
entries[217901] = { ["name"] = "Timeless Drums", ["text"] = "Use: Increases Haste by 15% for all party and raid members. Lasts 40 sec.\n\nAllies receiving this effect will become Exhausted and be unable to benefit from Bloodlust, Heroism, or similar effects again for 10 min. (2 Min Cooldown)\nRequires level 10 to 80 ( 80)" }
entries[217902] = { ["name"] = "Timerunner's Vial", ["text"] = "Use: Increases your mana regeneration by 1000% for 6 sec.\n\nReduces movement speed by 50%. (6 Sec Cooldown)\nRequires level 10 to 80 ( 80)" }
entries[217903] = { ["name"] = "Vindication", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: 10% of your damage is collected as Vindication. Every 3 sec, Vindication is consumed to heal up to 3 allies within 50 yards for the amount consumed.\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
entries[217904] = { ["name"] = "Timerunner's Draught of Power", ["text"] = "Use: Restores 525000 mana and increases Primary Stat by 3% for 30 min. (5 Min Cooldown)\nRequires level 10 to 80 ( 80)\n\"Additional stock can be purchased from Nostwin at any Infinite Bazaar.\"" }
entries[217905] = { ["name"] = "Timerunner's Draught of Health", ["text"] = "Use: Restores 1050000 health and increases Stamina by 3% for 30 min. (5 Min Cooldown)\nRequires level 10 to 80 ( 80)\n\"Additional stock can be purchased from Nostwin at any Infinite Bazaar.\"" }
entries[217906] = { ["name"] = "Drake Treat", ["text"] = "Unique (3)\nUse: Fully restores Skyriding Charges and grants a burst of flying speed. Only usable while dragonriding. (15 Sec Cooldown)\nRequires level 10 to 80 ( 80)" }
entries[217907] = { ["name"] = "Warmth", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: Healing taken is increased by 10%. 75% of overhealing taken is collected as Warmth. Every 5 sec, Warmth is consumed to heal an injured ally within 50 yards for the amount consumed.\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
entries[217925] = { ["name"] = "Bottle of Bees", ["text"] = "Binds when picked up\nUnique (3)\nUse: Annoy every enemy within 40 yards of the destination, engaging them in combat and applying Welts for 30 sec. Only usable outdoors.\n\nWelts :\nCauses an enemy to take 5% increased damage for 30 sec. Damaging the enemy has a chance to apply more Welts. (1 Min Cooldown)\nRequires level 10 to 80 ( 80)\n\"Buzzing with anger.\"" }
entries[217926] = { ["name"] = "Bottle of Dead Bees", ["text"] = "Use: Deals 26250 Physical damage to enemies within 3 yards. (1 Min Cooldown)\nRequires level 10 to 80 ( 80)\n\"Oops.\"" }
entries[217927] = { ["name"] = "Savior", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: Healing an ally beneath 35% health will grant them a shield absorbing 50% of the amount healed.\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
entries[217928] = { ["name"] = "Timeless Scroll of Resurrection", ["text"] = "Use: Brings a dead ally back to life with 35% health and mana. Cannot be cast when in combat. (30 Sec Cooldown)\nRequires level 10 to 80 ( 80)" }
entries[217929] = { ["name"] = "Timeless Scroll of Cleansing", ["text"] = "Use: Dispels all harmful curse, magic, poison, and disease effects from the target ally. (30 Sec Cooldown)\nRequires level 10 to 80 ( 80)\n\"Time heals all wounds, diseases, curses, hangovers...\"" }
entries[217930] = { ["name"] = "Nostwin's Voucher", ["text"] = "Use: Returns you to a nearby Infinite Bazaar. (15 Min Cooldown)\nRequires level 10 to 80 ( 80)\n\"Thanks for shopping, come back soon!\"" }
entries[217956] = { ["name"] = "Timeless Scroll of Summoning", ["text"] = "Use: Begins a ritual that creates a summoning portal for 3 min. The summoning portal can be used by allies to summon a targeted party or raid member. (30 Sec Cooldown)\nRequires level 10 to 80 ( 80)" }
entries[217957] = { ["name"] = "Deliverance", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: 4% of healing is collected as Deliverance. If an ally is below 50% health after receiving healing from you, Deliverance will be consumed to heal up to 3 allies within 50 yards for the amount consumed, divided evenly.\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
entries[217958] = { ["name"] = "Used Socks", ["text"] = "\"Unfortunately, it seems there was more than just treasure in these chests.\"\nSell Price:" }
entries[217959] = { ["name"] = "Incomplete Painting", ["text"] = "\"A painting that vaguely depicts a life filled with riches, though much of the details are missing.\"\nSell Price:" }
entries[217960] = { ["name"] = "Forgotten Key", ["text"] = "Binds when picked up\nUnique\n\"Who would keep a key for a chest in a chest?\"" }
entries[217961] = { ["name"] = "Righteous Frenzy", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: Healing an ally will send them into a Righteous Frenzy, consuming 2% health every second and granting 7% increased Haste for 5 sec.\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
entries[217962] = { ["name"] = "Dud Bomb", ["text"] = "\"Luckily, this appears to be inactive.\"\nSell Price:" }
entries[217964] = { ["name"] = "Holy Martyr", ["text"] = "Tinker Gem\nBinds when picked up\nUnique\nEquip: 5% of damage suffered is collected as Holy Martyrdom. Every 3 sec, Holy Martyrdom is consumed to heal 4 injured allies within 50 yards for the amount consumed. This effect cannot heal the Martyr.\nRequires level 10 to 80 ( 80)\n\"Fits in a Tinker socket.\"" }
entries[217965] = { ["name"] = "Repair Kit", ["text"] = "\"The sound of tools rustling around in here is enough to make you want to fix something.\"" }
entries[217969] = { ["name"] = "Bomb Debris", ["text"] = "\"Unluckily, this one was still active.\"\nSell Price:" }
entries[217983] = { ["name"] = "Disengage", ["text"] = "Cogwheel Gem\nBinds when picked up\nUnique\nEquip: Learn the following spell.\n\nDisengage\nLeap backwards, clearing movement impairing effects, and increasing your movement speed by 25% for 4 sec.\nRequires level 10 to 80 ( 80)\n\"Fits in a Cogwheel socket.\"" }
entries[217985] = { ["name"] = "Remembered Golden Gryphon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount. The capabilities of this mount depend on your Riding skill and location.\nSummons and dismisses a rideable Remembered Golden Gryphon mount. The capabilities of this mount depend on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"They love lions in Stormwind, and the gryphon is half lion. This is why these creatures are an air travel staple throughout the Alliance.\"\nVendor:\nRemembrancer Amuul\nZone:\nDalaran\nCost:\n25" }
entries[217986] = { ["name"] = "\"Delicious\" Egg Parts", ["text"] = "\"Kobold chefs around the Undermine agree! No meal is complete without these eggs.\"" }
entries[217987] = { ["name"] = "Remembered Wind Rider", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount. The capabilities of this mount depend on your Riding skill and location.\nSummons and dismisses a rideable Green Wind Rider mount. The capabilities of this mount depend on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Hundreds of battles across a dozen campaigns have been fought and won on the backs of these honored creatures.\"\nVendor:\nRemembrancer Amuul\nZone:\nDalaran\nCost:\n25" }
